Here’s a simple reusable React countdown timer component that counts down from a given number of seconds.

### CountdownTimer.jsx
```jsx
import React, { useEffect, useState } from "react";

function CountdownTimer({ initialSeconds = 60, onComplete }) {
  const [secondsLeft, setSecondsLeft] = useState(initialSeconds);
  const [isRunning, setIsRunning] = useState(true);

  useEffect(() => {
    if (!isRunning || secondsLeft <= 0) return;

    const intervalId = setInterval(() => {
      setSecondsLeft((prev) => {
        if (prev <= 1) {
          clearInterval(intervalId);
          setIsRunning(false);
          if (onComplete) onComplete();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(intervalId);
  }, [isRunning, secondsLeft, onComplete]);

  const formatTime = (totalSeconds) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
  };

  const handleReset = () => {
    setSecondsLeft(initialSeconds);
    setIsRunning(true);
  };

  return (
    <div style={{ fontFamily: "sans-serif", textAlign: "center" }}>
      <h2>Countdown Timer</h2>
      <div style={{ fontSize: "2rem", margin: "1rem 0" }}>
        {formatTime(secondsLeft)}
      </div>
      <button onClick={() => setIsRunning((prev) => !prev)}>
        {isRunning ? "Pause" : "Resume"}
      </button>
      <button onClick={handleReset} style={{ marginLeft: "0.5rem" }}>
        Reset
      </button>
    </div>
  );
}

export default CountdownTimer;
```

### Usage
```jsx
import React from "react";
import CountdownTimer from "./CountdownTimer";

function App() {
  return (
    <div>
      <CountdownTimer
        initialSeconds={90}
        onComplete={() => alert("Time's up!")}
      />
    </div>
  );
}

export default App;
```

### Notes
- `initialSeconds` sets the starting countdown value.
- `onComplete` runs when the timer hits zero.
- Includes **Pause**, **Resume**, and **Reset** controls.

